package nexussMarket.adapters.out.persistence.mongodb.documents;

import java.time.LocalDateTime;

import org.springframework.data.annotation.Id;
import org.springframework.data.mongodb.core.index.CompoundIndex;
import org.springframework.data.mongodb.core.mapping.Document;

import lombok.Getter;
import lombok.NoArgsConstructor;
import lombok.Setter;

/**
 * An append-only stock movement. Its {@code id} is generated by MongoDB,
 * since movements have no identifier in the domain.
 */
@Document(collection = "inventory_movements")
@CompoundIndex(name = "product_warehouse_occurred",
        def = "{'productId': 1, 'warehouseId': 1, 'occurredAt': 1}")
@Getter
@Setter
@NoArgsConstructor
public class InventoryMovementDocument {

    @Id
    private String id;

    private String productId;
    private String warehouseId;
    private String type;
    private int quantity;
    private LocalDateTime occurredAt;
}
